// Turns the raw iOS Shortcut POST body into a ready-to-send Notion page payload.
// Nothing downstream needs to know the shape of the Shortcut's JSON.

const MAX_BLOCK_CHARS = 1900; // Notion caps a rich_text object at 2000 chars
const MAX_TITLE_CHARS = 200;
const MAX_CHILDREN = 95;      // Notion caps a page-create at 100 children
const MAX_OVERFLOW = 100;     // ...and a block-append at 100 more

const toNumber = (v) => {
  if (v === null || v === undefined || v === '') return null; // Number('') is 0, which is a lie
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

// Break on paragraph, then word, then hard-cut — so blocks split where a human would.
const chunkText = (text, size) => {
  const chunks = [];
  let rest = text;
  while (rest.length > size) {
    let cut = rest.lastIndexOf('\n', size);
    if (cut < size * 0.5) cut = rest.lastIndexOf(' ', size);
    if (cut < size * 0.5) cut = size;
    chunks.push(rest.slice(0, cut).trim());
    rest = rest.slice(cut).trim();
  }
  if (rest) chunks.push(rest);
  return chunks;
};

const paragraph = (content) => ({
  object: 'block',
  type: 'paragraph',
  paragraph: { rich_text: [{ type: 'text', text: { content } }] },
});

return $input.all().map((item) => {
  const cfg = item.json;
  const body = cfg.body ?? {};
  const errors = [];

  const captureId = String(body.captureId ?? '').trim();
  const transcript = String(body.transcript ?? '').trim();
  let title = String(body.title ?? '').trim();

  if (!captureId) errors.push('captureId is required');
  if (!transcript && !title) errors.push('at least one of title or transcript is required');

  // Title falls back to the first sentence of the transcript.
  if (!title && transcript) {
    title = transcript.split(/(?<=[.!?])\s/)[0] || transcript;
  }
  if (title.length > MAX_TITLE_CHARS) {
    title = title.slice(0, MAX_TITLE_CHARS - 1).trimEnd() + '…';
  }

  // captureId carries its own timestamp: YYYYMMDD-HHMM__slug
  let capturedAt = null;
  const stamp = captureId.match(/^(\d{4})(\d{2})(\d{2})-(\d{2})(\d{2})/);
  if (stamp) {
    capturedAt = `${stamp[1]}-${stamp[2]}-${stamp[3]}T${stamp[4]}:${stamp[5]}:00`;
  }

  const duration = toNumber(body.duration);
  const sizeBytes = toNumber(body.size);
  const sizeMb = sizeBytes === null ? null : Math.round((sizeBytes / 1048576) * 100) / 100;
  const wordCount = transcript ? transcript.split(/\s+/).filter(Boolean).length : 0;
  const device = String(body.device ?? '').trim() || null;

  const properties = {
    'Name': { title: [{ type: 'text', text: { content: title || captureId } }] },
    'Capture ID': { rich_text: [{ type: 'text', text: { content: captureId } }] },
    'Status': { select: { name: cfg.defaultStatus || 'Inbox' } },
    'Source': { select: { name: 'iOS Shortcut' } },
    'Word Count': { number: wordCount },
  };
  // Notion creates the select option on the fly when the device is a new one.
  if (device) properties['Device'] = { select: { name: device } };
  if (duration !== null) properties['Duration (s)'] = { number: duration };
  if (sizeMb !== null) properties['Size (MB)'] = { number: sizeMb };
  if (capturedAt) properties['Captured At'] = { date: { start: capturedAt } };

  const meta = [
    device,
    duration !== null ? `${duration}s` : null,
    sizeMb !== null ? `${sizeMb} MB` : null,
    wordCount ? `${wordCount} words` : null,
  ].filter(Boolean).join('  ·  ');

  const children = [{
    object: 'block',
    type: 'callout',
    callout: {
      icon: { emoji: '📱' },
      color: 'gray_background',
      rich_text: [{ type: 'text', text: { content: [captureId, meta].filter(Boolean).join('  ·  ') } }],
    },
  }];

  let overflow = [];
  if (transcript) {
    children.push({
      object: 'block',
      type: 'heading_2',
      heading_2: { rich_text: [{ type: 'text', text: { content: 'Transcript' } }] },
    });
    const chunks = chunkText(transcript, MAX_BLOCK_CHARS).map(paragraph);
    children.push(...chunks.slice(0, MAX_CHILDREN));
    // Beyond ~370k characters the transcript is genuinely cut; say so on the page
    // rather than dropping it silently, and keep the append batch at Notion's 100.
    if (chunks.length > MAX_CHILDREN + MAX_OVERFLOW) {
      overflow = chunks.slice(MAX_CHILDREN, MAX_CHILDREN + MAX_OVERFLOW - 1);
      overflow.push(paragraph('⚠️ Transcript truncated — exceeded the Notion block ceiling for one capture.'));
    } else {
      overflow = chunks.slice(MAX_CHILDREN);
    }
  }

  return {
    json: {
      valid: errors.length === 0,
      errors,
      captureId,
      title,
      device,
      duration,
      sizeBytes,
      sizeMb,
      wordCount,
      capturedAt,
      notionDatabaseId: cfg.notionDatabaseId,
      notionVersion: cfg.notionVersion,
      properties,
      children,
      overflow,
      hasOverflow: overflow.length > 0,
    },
  };
});
